"""Style guide (STYLE schema) -> a Luau Tokens module, generated by code so every builder reads the same values.

Agents write the style guide; nobody hand-edits Tokens.luau. Invalid values are repaired to safe defaults and
reported, so a bad token never breaks the game at load time.
"""
from __future__ import annotations

import re

EASINGS = {"Linear", "Sine", "Quad", "Cubic", "Quart", "Quint", "Exponential", "Circular", "Back", "Elastic", "Bounce"}
WEIGHTS = {"Thin", "ExtraLight", "Light", "Regular", "Medium", "SemiBold", "Bold", "ExtraBold", "Heavy"}
REQUIRED_COLORS = ("bg", "surface", "surface_raised", "text", "text_muted", "primary", "secondary", "success",
                   "warning", "danger")
DEFAULT_COLORS = {"bg": "#101318", "surface": "#1B2029", "surface_raised": "#262D39", "text": "#F4F6FA",
                  "text_muted": "#A7B0C0", "primary": "#FFB02E", "secondary": "#4FC3F7", "success": "#5BD67A",
                  "warning": "#FFD34D", "danger": "#FF5A5A"}
DEFAULT_SIZES = {"display": 72, "h1": 44, "h2": 32, "body": 22, "caption": 16, "numeric": 28}
_HEX = re.compile(r"^#?([0-9a-fA-F]{6})$")
_IDENT = re.compile(r"[^A-Za-z0-9_]")


def _hex(v, fallback: str, problems: list[str], name: str) -> str:
    m = _HEX.match(str(v).strip()) if v is not None else None
    if not m:
        problems.append(f"colour {name}={v!r} is not #RRGGBB; used {fallback}")
        return fallback
    return "#" + m.group(1).upper()


def _key(k: str) -> str:
    k = _IDENT.sub("_", str(k).strip()) or "x"
    return k if not k[0].isdigit() else "_" + k


def _num(v, fallback: float, lo: float, hi: float, problems: list[str], name: str) -> float:
    try:
        x = float(v)
    except (TypeError, ValueError):
        problems.append(f"{name}={v!r} is not a number; used {fallback}")
        return fallback
    if not lo <= x <= hi:
        problems.append(f"{name}={x} outside [{lo}, {hi}]; clamped")
        x = min(hi, max(lo, x))
    return x


def _font(spec: str, default_weight: str) -> tuple[str, str]:
    """'Montserrat:Bold' / 'GothamBlack' / 'rbxasset://fonts/families/X.json:Bold' -> (family-or-enum, weight)."""
    s = str(spec or "").strip()
    weight = default_weight
    head, sep, tail = s.rpartition(":")
    if sep and tail in WEIGHTS:          # a trailing ":Weight" (a bare rbxasset:// URI has no such suffix)
        s, weight = head, tail
    return (s or "BuilderSans"), weight


def _lua_str(s: str) -> str:
    return '"' + str(s).replace("\\", "\\\\").replace('"', '\\"').replace("\n", "\\n") + '"'


def build_tokens(style: dict) -> tuple[str, list[str]]:
    """Return (Tokens.luau source, list of problems that were repaired)."""
    p: list[str] = []
    pal = dict(style.get("palette") or {})
    colors = {}
    for k in REQUIRED_COLORS:
        colors[k] = _hex(pal.get(k), DEFAULT_COLORS[k], p, k) if k in pal else DEFAULT_COLORS[k]
        if k not in pal:
            p.append(f"palette missing {k}; used {DEFAULT_COLORS[k]}")
    for k, v in pal.items():
        if k not in colors:
            colors[_key(k)] = _hex(v, "#FF00FF", p, k)

    fonts_in = style.get("fonts") or {}
    fonts = {role: _font(fonts_in.get(role, ""), w) for role, w in
             (("display", "Bold"), ("heading", "Bold"), ("body", "Regular"), ("numeric", "SemiBold"))}

    sizes = dict(DEFAULT_SIZES)
    for k, v in (style.get("type_scale") or {}).items():
        sizes[_key(k)] = _num(v, DEFAULT_SIZES.get(k, 22), 8, 200, p, f"type_scale.{k}")

    radius = {"small": 6, "medium": 12, "large": 20}
    for k, v in (style.get("radius") or {}).items():
        radius[_key(k)] = _num(v, 8, 0, 200, p, f"radius.{k}")
    stroke = _num(style.get("stroke", 2), 2, 0, 12, p, "stroke")

    m = style.get("motion") or {}
    ease_out = str(m.get("ease_out", "Quint")).replace("Enum.EasingStyle.", "")
    ease_in = str(m.get("ease_in", "Quad")).replace("Enum.EasingStyle.", "")
    if ease_out not in EASINGS:
        p.append(f"motion.ease_out={ease_out!r} is not an EasingStyle; used Quint")
        ease_out = "Quint"
    if ease_in not in EASINGS:
        p.append(f"motion.ease_in={ease_in!r} is not an EasingStyle; used Quad")
        ease_in = "Quad"
    durs = {k: _num(m.get(k, d), d, 0.02, 5, p, f"motion.{k}") for k, d in
            (("fast", 0.12), ("base", 0.2), ("slow", 0.35), ("dramatic", 0.6))}

    L = style.get("lighting") or {}
    lighting = {
        "ClockTime": _num(L.get("ClockTime", 14), 14, 0, 24, p, "lighting.ClockTime"),
        "Brightness": _num(L.get("Brightness", 2), 2, 0, 10, p, "lighting.Brightness"),
        "ExposureCompensation": _num(L.get("ExposureCompensation", 0), 0, -3, 3, p, "lighting.ExposureCompensation"),
        "Ambient": _hex(L.get("Ambient", "#464646"), "#464646", p, "lighting.Ambient"),
        "OutdoorAmbient": _hex(L.get("OutdoorAmbient", "#808080"), "#808080", p, "lighting.OutdoorAmbient"),
    }

    out = ["-- Generated by cybus-harness from the game's style guide. Edit the style guide, not this file.",
           "local Tokens = {}", "", "Tokens.canvas = Vector2.new(1920, 1080)", "", "Tokens.color = {"]
    out += [f"\t{k} = Color3.fromHex({_lua_str(v)})," for k, v in colors.items()]
    out += ["}", "", "local function font(name: string, weight: string): Font",
            "\tlocal ok, f = pcall(function() return Font.fromEnum((Enum.Font :: any)[name]) end)",
            "\tlocal w = (Enum.FontWeight :: any)[weight] or Enum.FontWeight.Regular",
            "\tif ok and f then return Font.new(f.Family, w) end",
            "\tif string.find(name, \"rbxasset\", 1, true) then return Font.new(name, w) end",
            "\treturn Font.new(\"rbxasset://fonts/families/\" .. name .. \".json\", w)",
            "end", "", "Tokens.font = {"]
    out += [f"\t{role} = font({_lua_str(fam)}, {_lua_str(w)})," for role, (fam, w) in fonts.items()]
    out += ["}", "", "Tokens.size = {"]
    out += [f"\t{k} = {v:g}," for k, v in sizes.items()]
    out += ["}", "", "Tokens.space = { s1 = 4, s2 = 8, s3 = 12, s4 = 16, s5 = 24, s6 = 32, s7 = 48, s8 = 64 }", "",
            "Tokens.radius = {"]
    out += [f"\t{k} = UDim.new(0, {v:g})," for k, v in radius.items()]
    out += ["}", f"Tokens.stroke = {stroke:g}", "", "Tokens.motion = {"]
    out += [f"\t{k} = {v:g}," for k, v in durs.items()]
    out += [f"\teaseOut = Enum.EasingStyle.{ease_out},", f"\teaseIn = Enum.EasingStyle.{ease_in},", "}",
            "function Tokens.tween(kind: string?, style: Enum.EasingStyle?, direction: Enum.EasingDirection?): TweenInfo",
            "\treturn TweenInfo.new(Tokens.motion[kind or \"base\"] or Tokens.motion.base, style or Tokens.motion.easeOut,",
            "\t\tdirection or Enum.EasingDirection.Out)",
            "end", "", "Tokens.lighting = {"]
    out += [f"\t{k} = {v:g}," if isinstance(v, float) else f"\t{k} = Color3.fromHex({_lua_str(v)})," for k, v in lighting.items()]
    out += ["}", "", "return Tokens", ""]
    return "\n".join(out), p


def lighting_script(style: dict) -> str:
    """Edit-mode Luau that applies the style guide's lighting to the open place (Lighting + post effects)."""
    L = style.get("lighting") or {}
    p: list[str] = []
    lines = ["local Lighting = game:GetService(\"Lighting\")",
             f"Lighting.ClockTime = {_num(L.get('ClockTime', 14), 14, 0, 24, p, 'c'):g}",
             f"Lighting.Brightness = {_num(L.get('Brightness', 2), 2, 0, 10, p, 'b'):g}",
             f"Lighting.ExposureCompensation = {_num(L.get('ExposureCompensation', 0), 0, -3, 3, p, 'e'):g}",
             f"Lighting.Ambient = Color3.fromHex({_lua_str(_hex(L.get('Ambient', '#464646'), '#464646', p, 'a'))})",
             f"Lighting.OutdoorAmbient = Color3.fromHex({_lua_str(_hex(L.get('OutdoorAmbient', '#808080'), '#808080', p, 'o'))})",
             "local function ensure(class, name)",
             "\tlocal x = Lighting:FindFirstChild(name) or Instance.new(class)",
             "\tx.Name = name; x.Parent = Lighting; return x",
             "end"]
    groups = (("atmosphere", "Atmosphere", "Atmosphere"), ("color_correction", "ColorCorrectionEffect", "ColorCorrection"),
              ("bloom", "BloomEffect", "Bloom"))
    for key, cls, name in groups:
        props = L.get(key) or {}
        if not props:
            continue
        lines.append(f"do local x = ensure({_lua_str(cls)}, {_lua_str(name)})")
        for k, v in props.items():
            k = _key(k)
            if isinstance(v, (int, float)):
                lines.append(f"\tpcall(function() x.{k} = {float(v):g} end)")
            elif isinstance(v, str) and _HEX.match(v.strip()):
                lines.append(f"\tpcall(function() x.{k} = Color3.fromHex({_lua_str(_hex(v, '#FFFFFF', p, k))}) end)")
        lines.append("end")
    lines.append("return \"lighting applied\"")
    return "\n".join(lines)
